content.query:
// Top storage operations by volume
StorageBlobLogs
| where TimeGenerated {timeRange}
| summarize RequestCount = count(), AvgLatencyMs = avg(DurationMs) by OperationName
| top 20 by RequestCount desc
| project Operation = OperationName, RequestCount, AvgLatencyMs = round(AvgLatencyMs, 1)

// Anonymous access attempts
StorageBlobLogs
| where TimeGenerated {timeRange}
| where AuthenticationType == 'anonymous'
| summarize AnonymousRequests = count() by AccountName, CallerIpAddress, OperationName
| top 20 by AnonymousRequests desc

// Throttled requests (HTTP 429 / 503) over time
StorageBlobLogs
| where TimeGenerated {timeRange}
| where StatusCode == 429 or StatusCode == 503
| summarize ThrottledCount = count() by bin(TimeGenerated, 1h), AccountName
| order by TimeGenerated asc
